head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > invalidMessageFunc]<br/>입력값 유효성 체크가 실패로 처리된 경우 메시지를 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "메시지를 생성할 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 반환값이 새로운 메시지로 적용됩니다.",
        "displaymessage=true 이고 validate() 메소드 실행결과가 실패일때 동작합니다.",
        "displaymessage=true 이고 validateObject() 메소드 실행결과가 실패일때 동작합니다.",
        "사용자 정의 함수에서 반환된 값은 alert() 메소드로 표시됩니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트의 렌더링 ID 를 갖는 callerId 속성을 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트를 반환하는 getCaller() 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실패한 항목을 문자열로 반환하는 getType() 메소드 ('mandatory', 'maxLength', 'maxByteLength', 'minLength', 'minByteLength', 'allowChar', 'ignoreChar' 값을 가짐) 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실패한 항목의 속성값을 반환하는 getValue() 메소드를 사용할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn) 
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}

scwin.check_validateObject = function (target) {
    let rtnObj  = target.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("validateObject : "+ rtnObj);

    if (rtnObj) {
        let callerId = rtnObj.callerId
        let type = rtnObj.type
        let value = rtnObj.value

        wf_body_bottom.getObj("scwin").setReturnValue("callerId : "+ callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : "+ type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : "+ value);
    }
}


scwin.fn_msg = function() { 
    let invalidCompId = this.callerId;  // invalid id 
    let invalidCompObj = this.getCaller();  // invalid obj
    let invalidType = this.getType();  // invalid type 
    let invalidValue = this.getValue(); // invalid value

        debugger;

    switch (invalidType) {
        case "mandatory" :
            msg = "Information is required.";
            break;
        case "minLength" :
            msg = "Minimum " + invalidValue + " digits are required.";
            break;
        case "minByteLength" :
            msg = "Minimum " + invalidValue + " bytes are required.";
            break;
        case "maxLength" :
            msg = "Maximum " + invalidValue + " digits are required.";
            break;     
        case "maxByteLength" :
            msg = "Maximum " + invalidValue + " bytes are required.";
            break;     
        case "allowChar" :
            msg = "allowChar " + invalidValue + " strings are required.";
            break;     
        case "ignoreChar" :
            msg = "ignoreChar " + invalidValue + " strings are required.";
            break;        
        default :
            msg = "Not valid.";
            break;
    }
    msg += "(id: " + invalidCompId + ", org_id: " + invalidCompObj.org_id + ")";

    return msg;
}


// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}

scwin.btn_validateObject1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validateObject(target1);
};


